<?php
function inventory_movement(int $stock,string $type,$document,$qty,$value,string $currency,?int $branch=null): void {
    global $pdo;$pdo->prepare('INSERT INTO inventory_movements (shop_id,stock_id,document_type,document_id,quantity_delta,value_delta,currency_code,actor_id) VALUES (?,?,?,?,?,?,?,?)')->execute([$branch??shop_id(),$stock,$type,(string)$document,$qty,$value,$currency,$_SESSION['user_id']??null]);
    if(in_array($type,['count_adjustment','transfer_out','transfer_in'],true)&&dec_units($value)!==0){$amount=dec_units($value)<0?dec_mul($value,-1):dec_round($value);$counter=$type==='count_adjustment'?'5200':'1400';$lines=dec_units($value)>0?[['1200',$amount,0],[$counter,0,$amount]]:[[$counter,$amount,0],['1200',0,$amount]];finance_post($type,$document,$currency,date('Y-m-d'),'Inventory '.$type,$lines,$branch??shop_id());}
}
function inventory_return_sale(int $sale,string $reason): void {
    sale_return_post($sale,[],$reason,bin2hex(random_bytes(16)));
}
function inventory_count(int $stock,$actual,string $reason): void {
    global $pdo;domain_require('inventory.approve');$actual=inventory_quantity($actual,true);if(mb_strlen(trim($reason))<3)throw new InvalidArgumentException('Enter a reason.');
    $pdo->beginTransaction();try{
        $lock=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';$q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.$lock);$q->execute([$stock,shop_id()]);$r=$q->fetch();if(!$r)throw new RuntimeException('Item not found.',403);
        if(dec_units($actual,3)<dec_units($r['reserved_qty']??0,3))throw new InvalidArgumentException('Cancel reserved transfers before reducing physical stock below its reservation.');
        if(!empty($r['partner_id']))domain_require('partners.approve');if(!empty($r['mudaraba_id'])){domain_require('mudaraba.approve');if(!partner_account((int)$r['mudaraba_id']))throw new InvalidArgumentException('Review the partnership opening before stock-count adjustments.');}
        $delta=dec_sub($actual,$r['quantity'],3);$value=dec_mul(dec_add($r['purchase_price'],$r['expenses'],6),$actual);
        $pdo->prepare('UPDATE stock SET quantity=?,inventory_value=?,capital_amount=? WHERE id=? AND shop_id=?')->execute([$actual,$value,$value,$stock,shop_id()]);
        if(!empty($r['mudaraba_id'])&&dec_units($delta,3)!==0){$pdo->prepare('UPDATE mudaraba_contracts SET profit_known=0 WHERE id=? AND shop_id=?')->execute([$r['mudaraba_id'],shop_id()]);domain_audit('partner_stock_variance_review_required','mudaraba',$r['mudaraba_id'],['quantity_change'=>$delta,'reason'=>$reason]);}
        inventory_movement($stock,'count_adjustment',bin2hex(random_bytes(8)),$delta,dec_sub($value,inventory_value($r)),$r['currency_code']);domain_audit('count_adjusted','stock',$stock,['quantity'=>$actual,'value'=>$value,'reason'=>$reason],null,$r);$pdo->commit();
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function inventory_transfer_create(int $stock,int $destination,$qty,string $notes,array $ownership=[]): void {
 global $pdo;domain_require('inventory.create');$qty=inventory_quantity($qty);$dest=domain_branch($destination);if(!$dest||$destination===shop_id()||(int)$dest['business_id']!==domain_business_id())throw new RuntimeException('Invalid destination.',403);
 finance_atomic(function()use($pdo,$stock,$destination,$qty,$notes,$ownership){$q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$stock,shop_id()]);$s=$q->fetch();if(!$s||dec_units(dec_sub($s['quantity'],$s['reserved_qty'],3),3)<dec_units($qty,3))throw new InvalidArgumentException('Insufficient unreserved stock.');$release=[null,null,null];if(!empty($s['partner_id'])||!empty($s['mudaraba_id']))$release=partner_transfer_review($s,$ownership);$pdo->prepare('UPDATE stock SET reserved_qty=reserved_qty+? WHERE id=? AND shop_id=?')->execute([$qty,$stock,shop_id()]);$pdo->prepare('INSERT INTO inventory_transfers (business_id,source_shop_id,destination_shop_id,stock_id,quantity,notes,created_by,is_reserved,ownership_review,ownership_hash,ownership_reviewed_by) VALUES (?,?,?,?,?,?,?,1,?,?,?)')->execute([domain_business_id(),shop_id(),$destination,$stock,$qty,mb_substr($notes,0,500),auth_user()['id'],...$release]);domain_audit('transfer_reserved','transfer',$pdo->lastInsertId(),['destination'=>$destination,'quantity'=>$qty]);});
}
function inventory_transfer_accept(int $id): void {
    global $pdo;domain_require('inventory.approve');$pdo->beginTransaction();try{
        $lock=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';
        $q=$pdo->prepare('SELECT * FROM inventory_transfers WHERE id=? AND destination_shop_id=? AND status=?'.$lock);$q->execute([$id,shop_id(),'pending']);$t=$q->fetch();if(!$t)throw new RuntimeException('Transfer not available.',403);
        if((int)$t['business_id']!==domain_business_id())throw new RuntimeException('Business mismatch.',403);
        $source=domain_branch((int)$t['source_shop_id']);if(!$source||!shop_is_operational($source))throw new RuntimeException('Source branch unavailable.');
        $q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.$lock);$q->execute([$t['stock_id'],$t['source_shop_id']]);$r=$q->fetch();if(!$r||dec_units($r['quantity'],3)<dec_units($t['quantity'],3)||(!(int)$t['is_reserved']&&dec_units(dec_sub($r['quantity'],$r['reserved_qty'],3),3)<dec_units($t['quantity'],3)))throw new InvalidArgumentException('Source stock is insufficient.');
        if(!empty($r['partner_id'])||!empty($r['mudaraba_id']))partner_validate_transfer($t,$r);
        $cost=inventory_cost_for_quantity($r,$t['quantity']);$qty=dec_sub($r['quantity'],$t['quantity'],3);$value=dec_sub(inventory_value($r),$cost);$reserved=dec_sub($r['reserved_qty'],(int)$t['is_reserved']?$t['quantity']:0,3);if(dec_units($reserved,3)<0)throw new RuntimeException('Invalid reservation balance.');
        $pdo->prepare('UPDATE stock SET quantity=?,inventory_value=?,capital_amount=?,reserved_qty=? WHERE id=? AND shop_id=?')->execute([$qty,$value,$value,$reserved,$r['id'],$t['source_shop_id']]);
        // Map category by name in the receiving branch; preserve identity and weighted cost.
        $category=null;if(!empty($r['category_id'])){$q=$pdo->prepare('SELECT name FROM categories WHERE id=? AND shop_id=?');$q->execute([$r['category_id'],$t['source_shop_id']]);if($name=$q->fetchColumn()){$ins=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?'INSERT OR IGNORE':'INSERT IGNORE';$pdo->prepare("$ins INTO categories (name,shop_id) VALUES (?,?)")->execute([$name,shop_id()]);$q=$pdo->prepare('SELECT id FROM categories WHERE name=? AND shop_id=?');$q->execute([$name,shop_id()]);$category=(int)$q->fetchColumn();}}
        $line=array_merge($r,['category_id'=>$category,'partner_id'=>null,'mudaraba_id'=>null]);$identity=inventory_identity($line);$position=inventory_find_position($line,$lock);$qtyIn=dec_add($position['quantity']??0,$t['quantity'],3);$valueIn=dec_add($position?inventory_value($position):0,$cost);
        if($position){$new=(int)$position['id'];$pdo->prepare('UPDATE stock SET quantity=?,purchase_price=?,expenses=0,capital_amount=?,inventory_value=?,identity_key=?,sku=? WHERE id=? AND shop_id=?')->execute([$qtyIn,dec_div($valueIn,$qtyIn,6),$valueIn,$valueIn,$identity,$line['sku']?:($position['sku']??null),$new,shop_id()]);}
        else{$pdo->prepare('INSERT INTO stock (name,category_id,specifications,quantity,purchase_price,expenses,sale_price,warehouse_location,capital_amount,inventory_value,unit,currency_code,sale_currency_code,shop_id,barcode,sku,identity_key,country_of_origin,supplier_name) VALUES (?,?,?,?,?,0,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$r['name'],$category,$r['specifications'],$qtyIn,dec_div($valueIn,$qtyIn,6),$r['sale_price'],'',$valueIn,$valueIn,$r['unit'],$r['currency_code'],$r['sale_currency_code'],shop_id(),$r['barcode'],$r['sku'],$identity,$r['country_of_origin'],$r['supplier_name']]);$new=(int)$pdo->lastInsertId();}
        inventory_movement((int)$r['id'],'transfer_out',$id,'-'.$t['quantity'],'-'.$cost,$r['currency_code'],(int)$t['source_shop_id']);inventory_movement($new,'transfer_in',$id,$t['quantity'],$cost,$r['currency_code']);
        $pdo->prepare("UPDATE inventory_transfers SET status='received',received_by=?,received_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'")->execute([auth_user()['id'],$id]);domain_audit('transfer_received','transfer',$id,['source'=>$t['source_shop_id'],'destination'=>shop_id(),'quantity'=>$t['quantity']]);$pdo->commit();
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}

function inventory_transfer_cancel(int $id,bool $reject=false): void {
 global $pdo;domain_require($reject?'inventory.approve':'inventory.edit');finance_atomic(function()use($pdo,$id,$reject){$q=$pdo->prepare('SELECT * FROM inventory_transfers WHERE id=? AND status=?'.finance_lock());$q->execute([$id,'pending']);$t=$q->fetch();if(!$t||(int)($reject?$t['destination_shop_id']:$t['source_shop_id'])!==shop_id())throw new RuntimeException('Transfer unavailable in this branch.',403);if((int)$t['is_reserved']){$q=$pdo->prepare('UPDATE stock SET reserved_qty=reserved_qty-? WHERE id=? AND shop_id=? AND reserved_qty>=?');$q->execute([$t['quantity'],$t['stock_id'],$t['source_shop_id'],$t['quantity']]);if($q->rowCount()!==1)throw new RuntimeException('Reservation balance is inconsistent.');}$pdo->prepare('UPDATE inventory_transfers SET status=? WHERE id=?')->execute([$reject?'rejected':'cancelled',$id]);domain_audit($reject?'transfer_rejected':'transfer_cancelled','transfer',$id);});
}
